const DCK=(()=>{
 const R=['ปุพเพ อะนะนุสสุเตสุ ธัมเมสุ,','จักขุง อุทะปาทิ ญาณัง อุทะปาทิ ปัญญา อุทะปาทิ,','วิชชา อุทะปาทิ อาโลโก อุทะปาทิ.'];
 const AR=[['ทุกขัง อะริยะสัจจัง','ปะริญเญยยันติ','ปะริญญาตันติ'],['ทุกขะสะมุทะโย อะริยะสัจจัง','ปะหาตัพพันติ','ปะหีนันติ'],['ทุกขะนิโรโธ อะริยะสัจจัง','สัจฉิกาตัพพันติ','สัจฉิกะตันติ'],['ทุกขะนิโรธะคามินี ปะฏิปะทา อะริยะสัจจัง','ภาเวตัพพันติ','ภาวิตันติ']];
 const twelve=AR.flatMap(([x,a,b])=>['อิทัง '+x.replace(/สัจจัง$/,'สัจจันติ')+' เม ภิกขะเว,',...R,'ตัง โข ปะนิทัง '+x+' '+a+' เม ภิกขะเว,',...R,'ตัง โข ปะนิทัง '+x+' '+b+' เม ภิกขะเว,',...R]);
 const F=['เอตัมภะคะวะตา พาราณะสิยัง อิสิปะตะเน มิคะทาเย,','อะนุตตะรัง ธัมมะจักกัง ปะวัตติตัง,','อัปปะฏิวัตติยัง สะมะเณนะ วา พราหมะเณนะ วา,','เทเวนะ วา มาเรนะ วา พรัหมุนา วา เกนะจิ วา โลกัสมินติ.'];
 const H=['ภุมมา','จาตุมมะหาราชิกา','ตาวะติงสา','ยามา','ตุสิตา','นิมมานะระตี','ปะระนิมมิตะวะสะวัตตี','พรัหมะปาริสัชชา','พรัหมะปุโรหิตา','มะหาพรัหมา','ปะริตตาภา','อัปปะมาณาภา','อาภัสสะรา','ปะริตตะสุภา','อัปปะมาณะสุภา','สุภะกิณหะกา','เวหัปผะลา','อะวิหา','อะตัปปา','สุทัสสา','สุทัสสี','อะกะนิฏฐะกา'];
 const gen=h=>h.endsWith('ี')?h+'นัง':h+'นัง';
 const devas=['ปะวัตติเต จะ ภะคะวะตา ธัมมะจักเก,','ภุมมา เทวา สัททะมะนุสสาเวสุง,',...F,...H.slice(1).flatMap((h,i)=>[gen(H[i])+' เทวานัง สัททัง สุตวา,',h+' เทวา สัททะมะนุสสาเวสุง,',...F])];
 return {twelve,devas};
})();
